<?php
declare(strict_types=1);
use BloodHub\Core\Database;
use BloodHub\Services\{BagTareResolver,PlateletResultCalculator,PlateletResultService,SampleTestSynchronizer};
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
spl_autoload_register(static function(string $class):void{$prefix='BloodHub\\';if(!str_starts_with($class,$prefix))return;$file=dirname(__DIR__).'/src/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($file))require $file;});
$pdo=Database::connection();$fail=[];$cp=$pdo->query("SELECT id,density FROM blood_components WHERE code='CP' AND status='active'")->fetch(PDO::FETCH_ASSOC);if(!$cp)$fail[]='CP ativo não encontrado.';$cpaf=$pdo->query("SELECT id,density FROM blood_components WHERE code='CPAF' AND status='active'")->fetch(PDO::FETCH_ASSOC);if(!$cpaf)$fail[]='CPAF ativo não encontrado.';if(!PlateletResultService::supports('CP')||!PlateletResultService::supports('CPAF')||PlateletResultService::supports('CH'))$fail[]='Classificação do renderer de plaquetas inválida.';
$sample=$pdo->query("SELECT s.id,s.bag_brand_id,s.blood_component_id FROM samples s JOIN blood_components bc ON bc.id=s.blood_component_id WHERE bc.code='CP' AND s.purpose='quality_control' AND s.status IN ('received','in_analysis','partial_results') ORDER BY s.id LIMIT 1")->fetch(PDO::FETCH_ASSOC);if(!$sample)$fail[]='Amostra CP em andamento não encontrada.';
if($sample&&$cp){$tare=BagTareResolver::resolve((int)$sample['bag_brand_id'],(int)$sample['blood_component_id']);if(!$tare)$fail[]='Tara CP não resolvida.';else{$gross=(float)$tare['tare_weight']+103.9;$base=['gross_weight'=>$gross,'tare_weight'=>$tare['tare_weight'],'density'=>$cp['density']];$volume=PlateletResultCalculator::calculate($base)['volume_ml'];if(abs($volume-100)>0.000001)$fail[]='Fórmula de volume divergente.';$cases=[
['platelet_method'=>'Sysmex','platelet_count'=>110,'expected'=>110*5*1000000*$volume,'key'=>'platelet_count_per_unit'],
['platelet_method'=>'Neubauer','platelet_count'=>2,'expected'=>2*5*10*200*1000*$volume,'key'=>'platelet_count_per_unit'],
['leukocyte_method'=>'Sysmex','leukocyte_count'=>3,'expected'=>3*1000000*$volume,'key'=>'leukocyte_count_per_unit'],
['leukocyte_method'=>'Neubauer','leukocyte_count'=>4,'expected'=>(4*10*20*1000*$volume)/4,'key'=>'leukocyte_count_per_unit'],
['leukocyte_method'=>'Nageotte','leukocyte_count'=>5,'expected'=>(5*10*1000*$volume)/50,'key'=>'leukocyte_count_per_unit']];foreach($cases as $case){$actual=PlateletResultCalculator::calculate($base+$case)[$case['key']];if(abs($actual-$case['expected'])>0.001)$fail[]='Fórmula divergente: '.json_encode($case);}}}
SampleTestSynchronizer::syncOpenSamples();$requiredCodes=['VOLUME','PLATELET_COUNT','PLATELETS_PER_UNIT','LEUKOCYTE_COUNT','LEUKOCYTES_PER_UNIT','PH','SWIRLING'];foreach(['CP','CPAF'] as $componentCode){$q=$pdo->prepare('SELECT t.code FROM test_blood_components tbc JOIN tests t ON t.id=tbc.test_id JOIN blood_components bc ON bc.id=tbc.blood_component_id WHERE bc.code=:code');$q->execute(['code'=>$componentCode]);$codes=$q->fetchAll(PDO::FETCH_COLUMN);foreach($requiredCodes as $code)if(!in_array($code,$codes,true))$fail[]="Teste {$componentCode} ausente: {$code}";}
$unsynced=(int)$pdo->query("SELECT COUNT(*) FROM samples s JOIN blood_components bc ON bc.id=s.blood_component_id JOIN test_blood_components tbc ON tbc.blood_component_id=s.blood_component_id WHERE bc.code='CP' AND s.purpose='quality_control' AND s.status IN ('received','in_analysis','partial_results') AND NOT EXISTS(SELECT 1 FROM sample_tests st WHERE st.sample_id=s.id AND st.test_id=tbc.test_id)")->fetchColumn();if($unsynced)$fail[]="Há {$unsynced} testes CP não sincronizados.";
$zero=PlateletResultCalculator::calculate(['volume_ml'=>100,'platelet_method'=>'Sysmex','platelet_count'=>0,'leukocyte_method'=>'Nageotte','leukocyte_count'=>0]);if($zero['platelet_count_per_unit']!==0.0||$zero['leukocyte_count_per_unit']!==0.0)$fail[]='Zero não foi preservado como resultado válido.';
if($fail){foreach($fail as $message)fwrite(STDERR,"FALHA: {$message}\n");exit(1);}fwrite(STDOUT,"OK: volume e cinco fórmulas FC0538 conferidos; testes das amostras CP existentes sincronizados.\n");
